import {int,pick,shuffle,random,range,esc,btn,input,select,note,metric,metrics,controls,grid,cell,log,finish,error,chance,lineSets,neighbors,largestSquare,SHAPES,transform,shapeHTML,parseIntField} from './core.js';
import {NAMES} from './data.js';

function virusBrief(s){let j=s.people.find(p=>p.role==='Journalist'&&p.alive);if(j){let candidates=s.people.filter((p,i)=>i&&p.alive&&!s.known[i]);if(candidates.length){let p=pick(s,candidates),i=s.people.indexOf(p);s.known[i]=p.role;log(s,`Private journalist report: seat ${i+1}, ${p.name}, is ${p.role}.`);}}}
function virusKill(s,i,why){let p=s.people[i];p.alive=false;p.infected=null;s.known[i]=p.role;log(s,`${p.name} was eliminated (${why}). Role revealed: ${p.role}.`);}
function virusCheck(s){if(s.people.filter(p=>p.role==='Terrorist').every(p=>!p.alive))finish(s,true,'The terrorists are gone',`You stopped the outbreak in round ${s.round}.`,s.round);else if(!s.people[0].alive)finish(s,false,'Your seat is empty','The officer was eliminated. The dossier reveals every role.');else if(s.cure>=2)finish(s,false,'A cure, but no arrests','The citizens won. As the neutral officer, your objective was to eliminate both terrorists.');else if(s.round>8)finish(s,false,'Time ran out','The solo session ended before both terrorists were eliminated.');}
export const virus={
create(s){let roles=shuffle(s,['Terrorist','Terrorist','Fanatic','Researcher','Researcher','Journalist',...Array(5).fill('Citizen')]);s.people=['Officer',...roles].map((role,i)=>({role,name:NAMES[i],alive:true,infected:null,bullet:1,antidote:1,claim:role==='Terrorist'||role==='Fanatic'?'Citizen':role}));s.antibody=pick(s,range(12).filter(i=>s.people[i].role==='Citizen'));s.round=1;s.cure=0;s.selected=1;s.known={'0':'Officer'};s.asked=[];s.talks=2;s.shot=false;s.tested=false;s.candidate=1;s.people[1+int(s,11)].infected=1;virusBrief(s);log(s,'One infection has been planted. Your badge is private.');},
view(s){let target=s.people[s.selected];return metrics(metric('Round',`${Math.min(8,s.round)} / 8`),metric('Alive',s.people.filter(p=>p.alive).length),metric('Infected',s.people.filter(p=>p.infected!==null&&p.alive).length),metric('Cure',`${s.cure} / 2`))+`<div class="seat-grid">${s.people.map((p,i)=>`<button class="seat ${i===s.selected?'selected':''} ${!p.alive?'eliminated':''}" data-act="seat" data-value="${i}"><span class="seat-no">${String(i+1).padStart(2,'0')}</span><span class="avatar a${i%4}">${p.name.slice(0,1)}</span><strong>${p.name}</strong><small>${s.outcome?p.role:s.known[i]||'Unknown role'}</small>${!p.alive?'<span class="dead-tag">Eliminated</span>':''}</button>`).join('')}</div>`+note(`Selected: <b>${target.name}</b>. ${s.known[s.selected]?`Verified role: ${s.known[s.selected]}.`:'Role unverified.'} Interviews left: ${s.talks}.`)+controls(btn('Interview','interview','','',!s.selected||!target.alive||!s.talks||s.asked.includes(s.selected)),btn(s.shot?'Shot used':'Shoot selected seat','shoot','','danger',!s.selected||!target.alive||s.shot),btn(s.tested?'Test used':'Test yourself','test','','',s.tested))+controls(select('candidate','Research candidate',s.people.map((p,i)=>[i,`${i+1}. ${p.name}`]).filter(([i])=>s.people[i].alive),s.candidate),btn('End round →','next','','primary'));},
act(s,a,v,p){if(a==='seat'){s.selected=+v;return;}if(a==='interview'){let t=s.people[s.selected];if(!s.talks||!t.alive||s.asked.includes(s.selected)||!s.selected)return;s.asked.push(s.selected);s.talks--;log(s,`${t.name}: “I am a ${t.claim.toLowerCase()}. ${pick(s,['I would compare the reports before acting.','Watch who survives the next wave.','The researchers need the antibody carrier.'])}”`);}if(a==='shoot'&&!s.shot&&s.selected&&s.people[s.selected].alive){virusKill(s,s.selected,'officer’s bullet');s.shot=true;virusCheck(s);}if(a==='test'&&!s.tested){s.tested=true;log(s,`Your one-time test: ${s.people[0].infected===null?'NEGATIVE':'POSITIVE'}.`);}if(a==='next'){
s.candidate=Number(p.candidate);let researchers=s.people.filter(p=>p.role==='Researcher'&&p.alive);if(researchers.length===2&&s.people[s.antibody].alive&&s.candidate===s.antibody){s.cure++;log(s,'The research task succeeded. Cure development advanced.');}else log(s,'The research task did not advance the cure.');
for(let t of s.people.filter(p=>p.role==='Terrorist'&&p.alive)){if(t.infected!==null&&t.antidote){t.infected=null;t.antidote=0;log(s,'A hidden antidote was used.');}if(t.bullet&&random(s)<.23){let victims=s.people.map((p,i)=>i).filter(i=>s.people[i].alive&&s.people[i].role!=='Terrorist');if(victims.length){virusKill(s,pick(s,victims),'a hidden bullet');t.bullet=0;}}}
s.round++;let spread=new Set();for(let i=0;i<12;i++){let q=s.people[i];if(q.alive&&q.infected!==null){for(let d of [-1,1]){let n=(i+d+12)%12;let steps=0;while(!s.people[n].alive&&steps++<12)n=(n+d+12)%12;if(s.people[n].alive&&s.people[n].infected===null)spread.add(n);}}}for(let i of spread)s.people[i].infected=s.round;
for(let i=0;i<12;i++){let q=s.people[i];if(!q.alive||q.infected===null)continue;if(i===s.antibody&&s.round>q.infected){q.infected=null;log(s,'Someone recovered naturally.');}else if(s.round-q.infected>=2)virusKill(s,i,'virus');}
s.shot=false;s.talks=2;s.asked=[];virusCheck(s);if(!s.outcome)virusBrief(s);log(s,`Round ${s.round} begins.`);
}}
};
const RULES=['When anyone is imprisoned, gain a ticket.','When you roll 1, move an extra space.','When anyone escapes, move forward 1.'];
const GROUPS=['No group rule','Rolling 2 moves an extra space','Escape also grants a ticket'];
function imprison(s,i){s.racers[i].prison=true;for(let p of s.racers)if(p.rule===0)p.tickets++;log(s,`${s.racers[i].name} went to prison. Ticket rules triggered.`);}
function escapeRace(s,i){let p=s.racers[i];p.prison=false;if(s.group===2)p.tickets++;for(let q of s.racers)if(q.rule===2&&!q.done)q.pos=Math.min(24,q.pos+1);}
function raceRoll(s,i,ticket=false){let p=s.racers[i];if(p.done)return;let face=ticket?'escape':pick(s,[1,1,2,3,'prison','escape']);if(ticket)p.tickets--;log(s,`${p.name} ${ticket?'spent a ticket':'rolled '+face}.`);if(p.prison){if(face==='escape')escapeRace(s,i);return;}if(face==='prison'){imprison(s,i);return;}if(face==='escape')return;p.pos=Math.min(24,p.pos+face+(p.rule===1&&face===1?1:0)+(s.group===1&&face===2?1:0));raceRank(s);if(!p.done&&p.pos&&p.pos%5===0){if(i===0)s.office=true;else{p.tickets++;log(s,`${p.name} took an office ticket.`);}}}
function raceRank(s){for(let p of s.racers)if(p.pos>=24&&!p.done){p.done=true;s.order.push(p.name);log(s,`${p.name} finished #${s.order.length}.`);}}
function raceBots(s){for(let i=1;i<4;i++)raceRoll(s,i,s.racers[i].prison&&s.racers[i].tickets>0);raceRank(s);if(s.racers[0].done||s.turn>=60){let rank=s.order.includes('You')?s.order.indexOf('You')+1:1+s.racers.slice(1).filter(p=>p.done||p.pos>=s.racers[0].pos).length;finish(s,rank===1,rank===1?'Your rule paid off':`You finished #${rank}`,`Track position ${s.racers[0].pos}/24 after ${s.turn} turns.`,rank);}}
export const race={create(s){s.phase='setup';s.racers=range(4).map((i)=>({name:NAMES[i],pos:0,tickets:0,rule:int(s,3),prison:false,done:false}));s.turn=0;s.group=0;s.order=[];s.office=false;},view(s){if(s.phase==='setup')return `<div class="center-intro"><span class="eyebrow">MAKE YOUR OWN ADVANTAGE</span><h2>Write the rule.<br>Then play the game.</h2></div>${RULES.map((r,i)=>btn(`<span class="choice-index">0${i+1}</span>${r}`,'rule',i,'rule-choice')).join('')}`;
return metrics(metric('Turn',s.turn),metric('Your tickets',s.racers[0].tickets),metric('Your rule',String(s.racers[0].rule+1).padStart(2,'0')))+`<div class="racetrack">${range(25).map(i=>`<div class="track-cell ${i&&i%5===0&&i<24?'office':''}"><small>${i===24?'FIN':i===0?'GO':i%5===0?'OFF':i}</small><div>${s.racers.map((p,j)=>p.pos===i?`<span class="pawn p${j}" title="${p.name}${p.prison?' (in prison)':''}">${j===0?'Y':p.name[0]}${p.prison?'⌑':''}</span>`:'').join('')}</div></div>`).join('')}</div>`+note(`<b>Your rule:</b> ${RULES[s.racers[0].rule]}<br><b>Group rule:</b> ${GROUPS[s.group]}${s.racers[0].prison?'<br>You are in prison. Roll escape or use a ticket.':''}`)+`<div class="legend">${s.racers.map((p,i)=>`<span><i class="dot p${i}"></i>${p.name}${p.prison?' · prison':''}</span>`).join('')}</div>`+(s.office?note('Office reached. Choose a benefit.')+controls(btn('Gain a ticket','office','ticket'),btn('Roll again','office','roll'),btn('Change group rule','office','group')):controls(btn('Roll die','roll','','primary'),btn('Use escape ticket','ticket','','',!s.racers[0].prison||!s.racers[0].tickets)));},act(s,a,v){if(a==='rule'){s.racers[0].rule=+v;s.phase='race';log(s,'Your personal rule is registered.');return;}if(s.office&&a!=='office')return;if(a==='office'){s.office=false;if(v==='ticket')s.racers[0].tickets++;if(v==='group'){s.group=(s.group+1)%3;log(s,`Group rule: ${GROUPS[s.group]}.`);}if(v==='roll')raceRoll(s,0);if(!s.office)raceBots(s);return;}if(a==='roll'||a==='ticket'){if(a==='ticket'&&(!s.racers[0].prison||!s.racers[0].tickets))return;s.turn++;raceRoll(s,0,a==='ticket');if(!s.office)raceBots(s);}}};

export function contact(a,b,type){if(type==='sum'){let x=a+b;return x<=20?'3–20':x>=180?'180–199':String(x);}if(type==='product')return String((a*b)%10);if(type==='quotient')return String(Math.floor(Math.max(a,b)/Math.min(a,b)));let count=0;for(let x=Math.min(a,b)+1;x<Math.max(a,b);x++)count+=(String(x).match(/0/g)||[]).length;return String(count);}
export function numberCandidates(s,who){let possible=range(100).map(i=>i+1);for(let h of s.contacts.filter(c=>c.a===who||c.b===who)){possible=possible.filter(x=>range(100).some(i=>{let y=i+1;return s.contacts.filter(c=>(c.a===who&&c.b===(h.a===who?h.b:h.a))||(c.b===who&&c.a===(h.a===who?h.b:h.a))).every(c=>contact(x,y,c.type)===c.result);}));}return possible;}
export const number={create(s){s.numbers=shuffle(s,range(100).map(i=>i+1)).slice(0,4);s.contacts=[];s.left=8;s.traded=null;s.guesses=['','','',''];},view(s){let candidates=numberCandidates(s,0);return metrics(metric('Contacts left',s.left),metric('Your candidates',candidates.length),metric('Players',4))+`<div class="number-players">${NAMES.slice(0,4).map((n,i)=>`<div><small>${n}</small><strong>?</strong><span>${i===0?'Your number':s.traded===i?'Knows your number':'Unknown number'}</span></div>`).join('')}</div>`+controls(select('partner','Contact partner',NAMES.slice(1,4).map((n,i)=>[i+1,n]),1),select('ticket','Ticket type',[['sum','+ Sum'],['product','× Product’s last digit'],['quotient','÷ Integer quotient'],['zeros','0 Zeros between']], 'sum'),btn('Make contact','contact','','primary',!s.left))+`<div class="contact-list">${s.contacts.map(c=>`<div><span>${NAMES[c.a]} + ${NAMES[c.b]}</span><small>${esc(c.type)}</small><strong>${esc(c.result)}</strong></div>`).join('')||'<p class="muted">Your contact results will appear here.</p>'}</div>`+note(`Possible values for your number: ${candidates.length>30?`${candidates.slice(0,30).join(', ')}…`:candidates.join(', ')}. This helper checks contacts with each partner; combine different partners’ clues yourself.`)+controls(btn('Trade with selected partner','trade','','',s.traded!==null))+`<h3>Submit your deductions</h3><div class="input-row">${NAMES.slice(0,4).map((n,i)=>input('guess'+i,n,s.guesses[i],1,100)).join('')}</div>`+controls(btn('Lock in all guesses','submit','','primary'));},act(s,a,v,p){if(a==='contact'&&s.left){let b=parseIntField(p,'partner',1,3),type=p.ticket;if(b===null||!['sum','product','quotient','zeros'].includes(type))return;s.contacts.push({a:0,b,type,result:contact(s.numbers[0],s.numbers[b],type)});s.left--;log(s,`Contact with ${NAMES[b]}: ${type} → ${s.contacts.at(-1).result}.`);}if(a==='trade'&&s.traded===null){let b=+p.partner;s.traded=b;log(s,`${NAMES[b]} shares a verified number: ${s.numbers[b]}. In return, they learned yours.`);}if(a==='submit'){let guess=range(4).map(i=>parseIntField(p,'guess'+i,1,100));if(guess[0]===null){error(s,'Enter your own number from 1 to 100. Other guesses can be blank.');return;}for(let i=1;i<4;i++)if(p['guess'+i]!==''&&guess[i]===null){error(s,'Each guess must be an integer from 1 to 100, or left blank.');return;}let score=guess[0]===s.numbers[0]?5:-5;for(let i=1;i<4;i++)if(guess[i]!==null)score+=guess[i]===s.numbers[i]?1:-1;if(guess.every((x,i)=>x===s.numbers[i]))score+=5;let guessedBy=0;for(let i=1;i<4;i++){let possibilities=range(100).map(x=>x+1).filter(x=>range(100).some(j=>s.contacts.filter(c=>c.b===i).every(c=>contact(x,j+1,c.type)===c.result)));let botGuess=s.traded===i?s.numbers[0]:pick(s,possibilities);if(botGuess===s.numbers[0])guessedBy++;}score-=guessedBy;finish(s,score>=6,score>=6?'The numbers reveal themselves':'A secret stays hidden',`${score} points, including −${guessedBy} for rivals who guessed yours. Numbers: ${s.numbers.map((n,i)=>`${NAMES[i]} ${n}`).join(' · ')}.`,score);}}};

const ANIMALS=['Snake','Parrot','Elephant','Lion','Monkey'];const ANIMAL_GLYPHS=['S','P','E','L','M'];
function animal(n){return `<span class="animal animal-${n}" title="${ANIMALS[n]}">${ANIMAL_GLYPHS[n]}</span>`;}
export function zooScore(board,seq,condition){let score=0;for(let l of lineSets(5,3)){let v=l.map(i=>board[i]);if(v.every((x,i)=>x===seq[i])||v.every((x,i)=>x===seq[2-i]))score++;}let counts=range(5).map(x=>board.filter(v=>v===x).length);return score*(counts[condition[0]]>counts[condition[1]]?2:1);}
function zooDeal(s){s.groups=range(2).map(()=>range(4).map(()=>int(s,5)));s.phase='bid';s.drop=0;}
function zooEnd(s){s.round++;if(s.round>5){let scores=s.sequences.map((sq,i)=>zooScore(s.board,sq,s.conditions[i]));let win=scores[0]>0&&scores[0]>=Math.max(...scores);finish(s,win,win?'A pattern worth bidding on':'The auction is over',scores.map((x,i)=>`${NAMES[i]}: ${x}`).join(' · ')+'. Tied top scores share victory; zero is a loss.',scores[0]);}else zooDeal(s);}
function zooDrop(s,col,tile){for(let y=4;y>=0;y--)if(s.board[y*5+col]===null){s.board[y*5+col]=tile;return true;}return false;}
function zooAuto(s,tiles,who){for(let tile of tiles){let legal=range(5).filter(c=>s.board[c]===null);if(!legal.length)break;let best=-Infinity,choice=legal[0];for(let c of legal){let b=[...s.board];for(let y=4;y>=0;y--)if(b[y*5+c]===null){b[y*5+c]=tile;break;}let val=zooScore(b,s.sequences[who],s.conditions[who])*10+random(s);if(val>best){best=val;choice=c;}}zooDrop(s,choice,tile);}}
export const zoo={create(s){s.board=Array(25).fill(null);s.credits=[30,30,30,30];s.sequences=range(4).map(()=>range(3).map(()=>int(s,5)));s.conditions=range(4).map(()=>shuffle(s,range(5)).slice(0,2));s.round=1;zooDeal(s);},view(s){return metrics(metric('Auction',`${Math.min(5,s.round)} / 5`),metric('Your credits',s.credits[0]),metric('Your score',zooScore(s.board,s.sequences[0],s.conditions[0])))+`<div class="zoo-layout"><div>${grid(5,s.board.map((a,i)=>cell(i,a===null?'<span class="empty-dot">·</span>':animal(a),'zoo-cell')))}<div class="column-controls">${range(5).map(i=>btn('↓','drop',i,'',s.phase!=='place'||s.board[i]!==null)).join('')}</div></div><div class="zoo-objective"><span class="eyebrow">YOUR SECRET SEQUENCE</span><div class="animal-row">${s.sequences[0].map(animal).join('')}<span>↔</span></div><p>Double your score if there are more <b>${ANIMALS[s.conditions[0][0]]}s</b> than <b>${ANIMALS[s.conditions[0][1]]}s</b>.</p><small>S Snake · P Parrot · E Elephant<br>L Lion · M Monkey</small></div></div>`+(s.phase==='bid'?`<div class="auction-groups">${s.groups.map((g,i)=>`<div><b>LOT ${i?'B':'A'}</b><div class="animal-row">${g.map(animal).join('')}</div></div>`).join('')}</div>`+controls(select('group','Your group',[[0,'A'],[1,'B']],0),input('bid','Credits to bid',Math.min(3,s.credits[0]),s.credits[0]?1:0,s.credits[0]),btn('Submit sealed bid','bid','','primary')):note(`You control lot ${s.won?'B':'A'}. Drop tile ${s.drop+1} of 4: <b>${ANIMALS[s.groups[s.won][s.drop]]}</b>. Click a column arrow.`));},act(s,a,v,p){if(a==='bid'&&s.phase==='bid'){let amount=parseIntField(p,'bid',s.credits[0]?1:0,s.credits[0]);if(amount===null){error(s,'Bid a whole number within your credit balance.');return;}let groups=[+p.group],bids=[amount];for(let i=1;i<4;i++){groups.push(int(s,2));bids.push(Math.min(s.credits[i],1+int(s,7)));}let totals=[0,0];bids.forEach((b,i)=>totals[groups[i]]+=b);if(totals[0]+totals[1]===0){log(s,'No credits remain. This auction closes without placement.');zooEnd(s);return;}let won=totals[0]===0?1:totals[1]===0?0:totals[0]<totals[1]?0:1;let contenders=range(4).filter(i=>groups[i]===won&&bids[i]>0);let max=Math.max(...contenders.map(i=>bids[i]));let winners=contenders.filter(i=>bids[i]===max);if(totals[0]===totals[1]||winners.length!==1){log(s,`Auction tied (A ${totals[0]} / B ${totals[1]}). Refunded and redealt.`);zooDeal(s);return;}s.credits=s.credits.map((x,i)=>x-bids[i]);s.won=won;let winner=winners[0];log(s,`A: ${totals[0]} · B: ${totals[1]}. Lower-total lot ${won?'B':'A'} wins. ${NAMES[winner]} controls placement.`);if(!winner){s.phase='place';s.drop=0;}else{zooAuto(s,s.groups[won],winner);zooEnd(s);}}if(a==='drop'&&s.phase==='place'){if(zooDrop(s,+v,s.groups[s.won][s.drop]))s.drop++;else error(s,'That column is full.');if(s.drop===4)zooEnd(s);}}};

export function grassLegal(board,n,p,shape,anchor){let ax=anchor%n,ay=Math.floor(anchor/n);let cells=shape.map(([x,y])=>[ax+x,ay+y]);if(cells.some(([x,y])=>x>=n||y>=n||board[y*n+x]!==0))return null;let ids=cells.map(([x,y])=>y*n+x);if(ids.some(i=>neighbors(i,n).some(j=>board[j]&&board[j]!==p)))return null;if(!ids.some(i=>neighbors(i,n).some(j=>board[j]===p)))return null;return ids;}
function grassBot(s){let candidates=[];for(let shape of s.offers)for(let r=0;r<4;r++)for(let anchor=0;anchor<144;anchor++){let cells=grassLegal(s.board,12,2,transform(shape,r),anchor);if(cells){let b=[...s.board];cells.forEach(i=>b[i]=2);candidates.push({cells,score:largestSquare(b,12,2)*20+cells.reduce((a,i)=>a+neighbors(i,12).filter(j=>s.board[j]===2).length,0)+random(s)*(s.difficulty==='hard'?1:12)});}}if(candidates.length){candidates.sort((a,b)=>b.score-a.score);candidates[0].cells.forEach(i=>s.board[i]=2);}else log(s,'Sage could not fit a piece and passed.');}
function grassNext(s){grassBot(s);s.round++;s.rot=0;s.flip=false;s.selected=0;if(s.round>9){let a=largestSquare(s.board,12,1),b=largestSquare(s.board,12,2);let area=s.board.filter(x=>x===1).length,botArea=s.board.filter(x=>x===2).length;let win=a>b||(a===b&&area>botArea);finish(s,win,win?'Room to grow':'The land is claimed',`Your largest square: ${a}×${a} (${area} cells). Sage: ${b}×${b} (${botArea} cells). Ties use area.`,a);}else s.offers=shuffle(s,SHAPES).slice(0,3);}
export const grass={create(s){s.board=Array(144).fill(0);s.board[26]=1;s.board[117]=2;s.round=1;s.selected=0;s.rot=0;s.flip=false;s.offers=shuffle(s,SHAPES).slice(0,3);},view(s){return metrics(metric('Round',`${Math.min(9,s.round)} / 9`),metric('Your square',`${largestSquare(s.board,12,1)}×${largestSquare(s.board,12,1)}`),metric('Sage’s square',`${largestSquare(s.board,12,2)}×${largestSquare(s.board,12,2)}`))+grid(12,s.board.map((v,i)=>cell(i,v?'':'',v===1?'land yours':v===2?'land theirs':'',''+v!=='0')),'grass-board')+`<div class="piece-tray">${s.offers.map((sh,i)=>btn(shapeHTML(transform(sh,s.rot,s.flip)),'piece',i,i===s.selected?'selected':'')).join('')}</div>`+controls(btn('Rotate ↻','rotate'),btn('Reflect ⇄','flip'),btn('Pass turn','pass'))+note('You are sage green. Sage is terracotta. Click the top-left anchor of your selected shape. Adjacent rival edges are forbidden.');},act(s,a,v){if(a==='piece')s.selected=+v;if(a==='rotate')s.rot=(s.rot+1)%4;if(a==='flip')s.flip=!s.flip;if(a==='cell'){let cells=grassLegal(s.board,12,1,transform(s.offers[s.selected],s.rot,s.flip),+v);if(!cells){error(s,'That placement must fit, touch your land, and keep an edge away from Sage.');return;}cells.forEach(i=>s.board[i]=1);log(s,'Your territory grew. Sage takes a turn.');grassNext(s);}if(a==='pass'){log(s,'You passed your tile.');grassNext(s);}}};

export function evaluate(nums,ops){let values=[nums[0]],operators=[];for(let i=0;i<ops.length;i++){if(ops[i]==='/'){if(nums[i+1]===0)return null;values[values.length-1]/=nums[i+1];}else{operators.push(ops[i]);values.push(nums[i+1]);}}let result=values[0];for(let i=0;i<operators.length;i++)result+=operators[i]==='+'?values[i+1]:-values[i+1];return Number.isFinite(result)?result:null;}
export function permutations(a){if(a.length<2)return [a];return a.flatMap((v,i)=>permutations(a.filter((_,j)=>i!==j)).map(rest=>[v,...rest]));}
function equationBot(s,cards){let best={distance:Infinity};let possibilities=permutations(cards),operators=permutations(['+','-','/']);if(s.difficulty==='relaxed')possibilities=shuffle(s,possibilities).slice(0,5);if(s.difficulty==='standard')possibilities=shuffle(s,possibilities).slice(0,12);for(let n of possibilities)for(let ops of operators){let value=evaluate(n,ops);if(value===null)continue;for(let target of [1,20]){let d=Math.abs(value-target);if(d<best.distance)best={value,distance:d,target,nums:n,ops};}}return best;}
function equationDeal(s){s.cards=range(4).map(()=>int(s,11));s.botCards=range(3).map(()=>range(4).map(()=>int(s,11)));s.order=[];s.ops=['+','-','/'];s.lane='1';}
export const equation={create(s){s.hand=1;s.chips=25;equationDeal(s);},view(s){let nums=s.order.map(i=>s.cards[i]);let value=s.order.length===4?evaluate(nums,s.ops):null;return metrics(metric('Hand',`${Math.min(5,s.hand)} / 5`),metric('Your chips',s.chips),metric('Starting stack',25))+`<div class="equation-targets"><span>LOW <b>1</b></span><i>or</i><span>HIGH <b>20</b></span></div><div class="number-cards">${s.cards.map((n,i)=>btn(`<small>CARD ${i+1}</small><strong>${n}</strong>${s.order.includes(i)?`<em>${s.order.indexOf(i)+1}</em>`:''}`,'card',i,s.order.includes(i)?'selected':'')).join('')}</div><div class="equation-line">${range(4).map((_,i)=>`<span>${nums[i]??'?'}</span>${i<3?select('op'+i,`Operator ${i+1}`,[['+','+'],['-','−'],['/','÷']],s.ops[i]):''}`).join('')}<b>= ${value===null?'?':Number(value.toFixed(4))}</b></div>`+controls(btn('Clear order','clear'),select('lane','Choose lane',[['1','Low · closest to 1'],['20','High · closest to 20']],s.lane),input('wager','Wager',Math.min(2,s.chips),1,Math.min(5,s.chips)),btn('Showdown','submit','','primary',s.order.length!==4),btn('Fold · −1','fold'))+note('Use each number card once and each operator (+ − ÷) once. Division is evaluated first. Bots build from separate hands. Your lane’s winner takes its pot; ties split.');},act(s,a,v,p){if(a==='card'){let i=+v;if(!s.order.includes(i))s.order.push(i);else s.order=s.order.filter(x=>x!==i);}if(a==='clear')s.order=[];if(a==='ops'){s.ops=[p.op0,p.op1,p.op2];s.lane=p.lane;return;}if(a==='fold'){s.chips--;log(s,'You folded and paid one chip.');}else if(a==='submit'){let wager=parseIntField(p,'wager',1,Math.min(5,s.chips));s.ops=[p.op0,p.op1,p.op2];s.lane=p.lane;if(wager===null||s.order.length!==4){error(s,'Choose all cards and a legal wager.');return;}if(new Set(s.ops).size!==3||!s.ops.every(x=>['+','-','/'].includes(x))){error(s,'Use +, − and ÷ exactly once each.');return;}let value=evaluate(s.order.map(i=>s.cards[i]),s.ops);if(value===null){error(s,'Division by zero is not a valid equation.');return;}let target=+p.lane,players=[{name:'You',value,target,distance:Math.abs(value-target)},...s.botCards.map((c,i)=>({name:NAMES[i+1],...equationBot(s,c)}))];let lane=players.filter(x=>x.target===target),best=Math.min(...lane.map(x=>x.distance)),winners=lane.filter(x=>Math.abs(x.distance-best)<1e-8);s.chips-=wager;let payout=winners.some(x=>x.name==='You')?lane.length*wager/winners.length:0;s.chips+=payout;log(s,`Your ${value.toFixed(3)} in ${target===1?'Low':'High'}: ${payout?'won '+payout.toFixed(1)+' chips':'lost '+wager+' chips'}.`);for(let q of players.slice(1))log(s,`${q.name}: ${q.value.toFixed(3)} → ${q.target===1?'Low':'High'}.`);}else return;
s.chips=Number(s.chips.toFixed(4));s.hand++;if(s.hand>5||s.chips<1){finish(s,s.chips>25,s.chips>25?'A calculated victory':'The house closes',`Final stack: ${Number(s.chips.toFixed(2))} chips. You started with 25.`,s.chips);}else equationDeal(s);}};
